 async function resolveDocs(list){if(!Array.isArray(list))return {text:'',paths:[]};let text='',budget=300000;const paths=[];for(const a of list){const m=/^[0-9a-f-]{36}\.(pptx|docx|xlsx|xls|pdf|txt|md|csv|tsv|json|xml|yaml|yml|toml|ini|log|html|css|js|mjs|cjs|ts|tsx|jsx|py|rb|go|rs|java|kt|swift|c|h|cpp|cs|php|sh|ps1|sql|vue|svelte)$/.exec(a?.id||'');if(!m)continue;const p=path.join(root,'data','uploads',a.id),name=String(a.name||a.id).slice(0,80);
  if(m[1]==='pptx'||m[1]==='docx'){let t='';try{t=await officeText(await readFile(p),m[1])}catch{}if(t&&t.length<=budget){budget-=t.length;text+='\n\nText of the attached '+(m[1]==='pptx'?'PowerPoint deck':'Word document')+' '+name+(m[1]==='pptx'?' (slide by slide, with speaker notes; images and layout are not included)':' (headings kept as Markdown)')+':\n````text\n'+t+'\n````'}}
  else if(m[1]==='xlsx'||m[1]==='xls'){let t='';try{const X=await import('xlsx');const wb=X.read(await readFile(p),{type:'buffer'});for(const n of wb.SheetNames.slice(0,8)){const csv=X.utils.sheet_to_csv(wb.Sheets[n],{blankrows:false}).split('\n').slice(0,3000).join('\n');t+='\n--- Sheet: '+n+' ---\n'+csv}}catch{}
   if(t&&t.length<=budget){budget-=t.length;text+='\n\nThe attached spreadsheet '+name+' as CSV (one block per sheet, up to 3,000 rows each):\n````csv'+t+'\n````'}}
  else if(m[1]!=='pdf'){let body='';try{body=await readFile(p,'utf8')}catch{throw Error('An attachment is missing. Attach it again.')}if(body.length<=budget){budget-=body.length;text+='\n\nAttached file '+name+':\n````'+m[1]+'\n'+body+'\n````';continue}}
  else{let t='';try{t=pdfText(await readFile(p))}catch{}if(readable(t)&&t.length<=budget){budget-=t.length;text+='\n\nText extracted from the attached PDF '+name+' (layout and images are not included; the file itself is listed below):\n````text\n'+t+'\n````'}}
  try{await access(p)}catch{throw Error('An attachment is missing. Attach it again.')}paths.push({name,path:p})}
  if(paths.length)text+='\n\nAttached file'+(paths.length>1?'s are':' is')+' saved outside the project folder; you may read '+(paths.length>1?'them':'it')+' (read-only) with your file tools or a command: '+paths.map(x=>x.name+' ('+x.path+')').join(', ');return {text,paths}}
